/**
 * Значок 🔊 над репликами (баблами) читалки.
 *
 * Один-единственный бейдж: пока TTS озвучивает реплику ([isSpeaking] — true),
 * показывается ровно ОДИН значок у текущего бабла (справа сверху от его рамки),
 * а не россыпь значков по странице. Когда озвучка не идёт, значков на данных
 * нет — остаётся только перетаскиваемый значок для ручной озвучки реплики.
 *
 * Координаты баблов — нормализованные 0..1 относительно изображения. Здесь они
 * маппятся на размер компоновки (как у [AutoReadHighlight] по умолчанию).
 */
@Composable
fun OcrBubbleVoiceOverlay(
    regions: List<AutoReadEngine.FrameRegion>,
    onSpeakRegion: (text: String, index: Int) -> Unit,
    modifier: Modifier = Modifier,
    perBubble: Boolean = true,
    draggable: Boolean = true,
    iconColor: Color = Color(0xFF00E5FF),
    isSpeaking: Boolean = false,
) {
    if (regions.isEmpty()) return
    BoxWithConstraints(
        modifier = modifier.fillMaxSize().semantics { contentDescription = "Бейдж озвучки реплик" },
    ) {
        val maxW = maxWidth
        val maxH = maxHeight
        val iconSize = 30.dp

        if (isSpeaking) {
            // ЕДИНЫЙ бейдж: один индикатор у реплики, которую TTS озвучивает
            // сейчас. Если рамка текущей реплики неизвестна — фиксируем значок
            // в верхнем правом углу страницы, чтобы он всё равно был виден.
            val current = regions.firstOrNull { it.state == AutoReadEngine.FrameRegion.State.CURRENT }
            if (current != null && current.text.isNotBlank() && current.box.isValidForIcon()) {
                val box = current.box
                val currentIndex = regions.indexOf(current)
                val xDp = (box.left * maxW.value).dp
                val yDp = (box.top * maxH.value).dp
                val wDp = ((box.right - box.left) * maxW.value).dp
                Box(
                    modifier = Modifier
                        .offset(x = xDp + wDp - iconSize, y = yDp - iconSize / 3)
                        .size(iconSize)
                        .pointerInput(currentIndex, current.text, onSpeakRegion) {
                            detectTapGestures { onSpeakRegion(current.text, currentIndex) }
                        }
                        .semantics {
                            contentDescription =
                                "Озвучить реплику ${current.index}: ${current.text.take(30)}"
                        },
                    contentAlignment = Alignment.Center,
                ) {
                    SpeakerBadge(color = iconColor, size = iconSize)
                }
            } else {
                Box(
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(top = 8.dp, end = 8.dp)
                        .size(iconSize),
                    contentAlignment = Alignment.Center,
                ) {
                    SpeakerBadge(color = iconColor, size = iconSize)
                }
            }
        } else if (draggable) {
            // Не звучит — только перетаскиваемый значок для ручной озвучки.
            DraggableSpeakIcon(regions = regions, onSpeakRegion = onSpeakRegion, accent = iconColor)
        }
    }
}

/** Круглая кнопка-значок озвучки. */
@Composable
private fun SpeakerBadge(color: Color, size: Dp) {
    Surface(
        shape = CircleShape,
        color = color.copy(alpha = 0.85f),
        contentColor = Color.Black,
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.4f)),
        modifier = Modifier.size(size),
    ) {
        Box(modifier = Modifier.size(size), contentAlignment = Alignment.Center) {
            Icon(
                Icons.Outlined.RecordVoiceOver,
                contentDescription = null,
                modifier = Modifier.padding(size / 4f),
            )
        }
    }
}

/** Один перетаскиваемый значок: при отпускании привязывается к ближайшему баблу. */
@Composable
private fun DraggableSpeakIcon(
    regions: List<AutoReadEngine.FrameRegion>,
    onSpeakRegion: (String, Int) -> Unit,
    accent: Color,
) {
    var posX by remember { mutableStateOf(0f) }
    var posY by remember { mutableStateOf(0f) }
    var placed by remember { mutableStateOf(false) }
    val density = LocalDensity.current

                onCopyText = onCopyText,
                onSpeak = onSpeak,
                onChooseVoice = onChooseVoice,
                onSpeakRole = onSpeakRole,
                onAddToDictionary = onAddToDictionary,
                onHidePageOverlay = onHidePageOverlay,
            )
        }
        presentation == OcrResultPresentation.POPUP && anchorRect != null -> {
            OcrResultPopup(
                onDismissRequest = onDismissRequest,
                anchorRect = anchorRect,
                settings = popupSettings,
                onCopyText = onCopyText,
                searchState = searchState,
                onQueryChange = onQueryChange,
                onSearch = onSearch,
                onTermGroupClick = onTermGroupClick,
                onPlayAudioClick = onPlayAudioClick,
                onSpeak = onSpeak,
                onChooseVoice = onChooseVoice,
                onSpeakRole = onSpeakRole,
                onAddToDictionary = onAddToDictionary,
                onHidePageOverlay = onHidePageOverlay,
            )
        }
        else -> {
            OcrResultBottomSheet(
                onDismissRequest = onDismissRequest,
                onCopyText = onCopyText,
                searchState = searchState,
                onQueryChange = onQueryChange,
                onSearch = onSearch,
                onTermGroupClick = onTermGroupClick,
                onPlayAudioClick = onPlayAudioClick,
                actions = {
                    OcrResultActionBar(
                        onSpeak = onSpeak,
                        onCopyText = onCopyText,
                        onChooseVoice = onChooseVoice,
                        onSpeakRole = onSpeakRole,
                        onAddToDictionary = onAddToDictionary,
                        onHidePageOverlay = onHidePageOverlay,
                    )
                },
            )
        }
    }
}

/**
 * Затемнение, тап по которому закрывает результат.
 *
 * Раньше блок был написан, но завёрнут в `if (false)`: карточка висела
 * поверх страницы, и закрыть её можно было только кнопкой в самой карточке
 * или аппаратной «назад». Теперь тап мимо карточки и по затемнению гасит
 * результат — то самое, чего не хватало.
 */
@Composable
private fun OcrDismissScrim(
    dim: Boolean,
    onDismissRequest: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Box(
        modifier = modifier
            .fillMaxSize()
            .then(
                if (dim) {
                    Modifier.background(MaterialTheme.colorScheme.scrim.copy(alpha = 0.32f))
                } else {
                    Modifier
                },
            )
            .clickable(
                indication = null,
                interactionSource = remember { MutableInteractionSource() },
                onClick = onDismissRequest,
            ),
    )
}

/**
 * Карточка распознанного текста без словарной части: текст можно скопировать
 * и озвучить, лишних сообщений «словари не найдены» нет.
 *
 * Карточка намеренно небольшая: текст ограничен по высоте и прокручивается
 * внутри, а действия собраны в одну строку иконок под ним. Раньше здесь были
 * два ряда подписей и отдельные плавающие кнопки — вместе они закрывали
 * половину экрана.
 */
@Composable
private fun OcrPlainTextCard(
    text: String,
    source: OcrTextSource?,
    dimBackground: Boolean,
    onDismissRequest: () -> Unit,
    onCopyText: () -> Unit,
    onSpeak: () -> Unit = {},
    onChooseVoice: () -> Unit = {},
    onSpeakRole: (String) -> Unit = {},
    onAddToDictionary: () -> Unit = {},
    onHidePageOverlay: (() -> Unit)? = null,
) {
    BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        // Не больше трети экрана: карточка не должна закрывать рисунок.
        val maxTextHeight = (maxHeight * 0.3f).coerceAtLeast(96.dp)

        OcrDismissScrim(dim = dimBackground, onDismissRequest = onDismissRequest)

        Surface(
            shape = RoundedCornerShape(16.dp),
            color = MaterialTheme.colorScheme.surfaceContainerHigh,
            tonalElevation = 6.dp,
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth()
                .padding(horizontal = 12.dp, vertical = 24.dp)
                // Гасим тап мимо текста, иначе тап по пустому месту карточки
                // закрывал бы результат вместо выделения текста.
                .clickable(
                    indication = null,
                    interactionSource = remember { MutableInteractionSource() },
                    onClick = {},
                ),
        ) {
            Column(modifier = Modifier.padding(start = 16.dp, end = 8.dp, top = 8.dp, bottom = 8.dp)) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(modifier = Modifier.weight(1f)) {
                        OcrEngineCaption(source)
                    }
                    IconButton(onClick = onDismissRequest) {
                        Icon(Icons.Outlined.Close, contentDescription = "Закрыть")
                    }
                }

                Text(
                    text = text,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurface,
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = maxTextHeight)
                        .verticalScroll(rememberScrollState())
                        .padding(end = 8.dp),
                )

                Spacer(modifier = Modifier.height(4.dp))
                HorizontalDivider()
                Spacer(modifier = Modifier.height(4.dp))

                OcrResultActionBar(
                    onSpeak = onSpeak,
                    onCopyText = onCopyText,
                    onChooseVoice = onChooseVoice,
                    onSpeakRole = onSpeakRole,
                    onAddToDictionary = onAddToDictionary,
                    onHidePageOverlay = onHidePageOverlay,
                    modifier = Modifier.fillMaxWidth(),
                )
            }
        }
    }
}

/**
 * Подпись «кто распознал» над распознанным текстом.
 *
 * Если текст прочитал не тот движок, который выбран в настройках (без сети
 * онлайн пропускается и читает локальный), это сказано прямо: иначе
 * читатель сравнивает качество двух разных движков и делает вывод, что они
 * одинаковые.
 */
@Composable
private fun OcrEngineCaption(source: OcrTextSource?) {
    if (source == null) return
    val engineName = stringResource(source.engine.titleRes)
    val text = if (source.usedInsteadOfSelected) {
        val selectedName = stringResource(selectedOcrModel().titleRes)
        stringResource(MR.strings.ocr_recognized_by_fallback, engineName, selectedName)
    } else {
        stringResource(MR.strings.ocr_recognized_by, engineName)
    }
    Text(
        text = text,
        style = MaterialTheme.typography.labelSmall,
        color = MaterialTheme.colorScheme.onSurfaceVariant,
    )
}

